command:
$ErrorActionPreference="Stop"
$main="09851775bf18340ccaf471313c380b474a17b7f6"
$candidate="029ef1e5d8f186bfc5262d386576204b58fa47a9"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$baseline=Join-Path $env:RUNNER_TEMP "fly-indexed-date-baseline-098517"
$changed=Join-Path $env:RUNNER_TEMP "fly-indexed-date-visual-029ef1"
if((Test-Path -LiteralPath $baseline) -or (Test-Path -LiteralPath $changed)){throw "Owned worktree collision"}
Set-Location -LiteralPath $repo
& git fetch origin main feat/search-v3-indexed-modified-date --no-tags
if($LASTEXITCODE -ne 0){throw "Git fetch failed"}
$head=(& git rev-parse refs/remotes/origin/main).Trim()
if($head -ne $main){throw "Main revision changed"}
$feature=(& git rev-parse refs/remotes/origin/feat/search-v3-indexed-modified-date).Trim()
if($feature -ne $candidate){throw "Candidate revision changed"}
try {
  & git worktree add --detach $baseline $main
  if($LASTEXITCODE -ne 0){throw "Baseline worktree failed"}
  & git worktree add --detach $changed $candidate
  if($LASTEXITCODE -ne 0){throw "Candidate worktree failed"}
  Set-Location -LiteralPath $changed
  & python -X utf8 -m py_compile tests/winui/test_indexed_search_gui.py tests/winui/indexed_search_visual_compare.py tests/winui/test_indexed_search_visual_compare.py
  if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_MATCHED_VISUAL_SYNTAX_FAIL"}
  & python -X utf8 -m unittest tests/winui/test_indexed_search_visual_compare.py
  if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_MATCHED_VISUAL_CONTRACT_FAIL"}
  Write-Host "INDEXED_DATE_MATCHED_VISUAL_CONTRACT=PASS"
  Set-Location -LiteralPath $baseline
  & cmd.exe /c build.bat Release
  if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_VISUAL_BASELINE_BUILD_FAIL"}
  Write-Host "INDEXED_DATE_VISUAL_BASELINE_BUILD=PASS"
  Set-Location -LiteralPath $changed
  & cmd.exe /c build.bat Release
  if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_VISUAL_AFTER_BUILD_FAIL"}
  Write-Host "INDEXED_DATE_VISUAL_AFTER_BUILD=PASS"
  $env:FLY_INDEXED_SEARCH_VISUAL_EXE=Join-Path $baseline "out\winui\Release\flyExplorer.exe"
  & python -X utf8 tests/winui/test_indexed_search_gui.py --configuration Release --capture before
  if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_VISUAL_BEFORE_FAIL"}
  Write-Host "INDEXED_DATE_VISUAL_BEFORE=PASS"
  Remove-Item Env:FLY_INDEXED_SEARCH_VISUAL_EXE -ErrorAction SilentlyContinue
  & python -X utf8 tests/winui/test_indexed_search_gui.py --configuration Release --capture after
  if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_VISUAL_AFTER_FAIL"}
  Write-Host "INDEXED_DATE_VISUAL_AFTER=PASS"
  $folder=Join-Path $changed "logs\search-v3-indexed"
  & python -X utf8 tests/winui/indexed_search_visual_compare.py --before (Join-Path $folder "indexed-search-before.bmp") --after (Join-Path $folder "indexed-search-after.bmp") --metadata (Join-Path $folder "date-matched-comparison.json") --require-matched
  if($LASTEXITCODE -ne 0){throw "INDEXED_DATE_VISUAL_COMPARE_FAIL"}
  Write-Host "INDEXED_DATE_VISUAL_REVIEW_CAPTURED=PASS"
} finally {
  Remove-Item Env:FLY_INDEXED_SEARCH_VISUAL_EXE -ErrorAction SilentlyContinue
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $changed){& git worktree remove --force $changed}
  if(Test-Path -LiteralPath $baseline){& git worktree remove --force $baseline}
  & git worktree prune
}
